//! Generation and maintenance of the user file (`src/<form>.rs`):
//! - Stub creation for new events;
//! - Incremental addition without overwriting manual code;
//! - Pruning of empty stubs generated by the IDE when unwired.

use crate::{Adicao, Ancora, Arquivo, Dono, Erro, elo, identificador};
use crawrad_ir::{Document, Node, NodeId};
use std::path::PathBuf;

use super::layout::emitido;
use crawrad_note::note;

pub const MARCA: &str = "\n    // New event handlers go here.\n";

pub const MARCAS_ACEITAS: &[&str] = &[
    MARCA,
    "\n    // Os handlers dos eventos novos entram aqui.\n",
];

#[note("targets-egui-stubs-marca-em")]
pub fn marca_em(texto: &str) -> Option<(usize, bool)> {
    for m in MARCAS_ACEITAS {
        if let Some(p) = texto.find(m) {
            return Some((p, false));
        }
        if let Some(p) = texto.find(&m.replace('\n', "\r\n")) {
            return Some((p, true));
        }
    }
    None
}

const CORPO_DO_STUB: &str = "        \n";

fn bloco_do_stub(
    reg: &crawrad_registry::Registry,
    classe: &str,
    componente: &str,
    evento: &str,
    f: &str,
    base_handler: Option<&str>,
) -> String {
    // The question lives OUTSIDE the target: both generators write the same
    // handler, and a second copy of this question would diverge from the first.
    let params = crate::events::method_params(reg, classe, evento);
    let body = match base_handler {
        Some(base_f) => {
            let args = crate::events::call_args_from_params(&params);
            format!("        self.base.{base_f}({args});\n")
        }
        None => CORPO_DO_STUB.to_string(),
    };
    format!(
        "\n    {}\n    pub fn {f}({params}) {{\n{body}    }}\n",
        marca_de_evento(componente, evento)
    )
}

fn marca_de_evento(componente: &str, evento: &str) -> String {
    format!("/// `{componente}.{evento}`")
}

#[note("targets-egui-stubs-todos-os-eventos")]
pub fn todos_os_eventos() -> Vec<&'static str> {
    let reg = crawrad_registry::Registry::builtin();
    let mut evs: Vec<&'static str> = reg
        .all()
        .flat_map(|d| d.events.iter().map(|e| e.name))
        .collect();
    evs.sort_unstable();
    evs.dedup();
    evs
}

pub fn eh_evento_conhecido(evento: &str) -> bool {
    let reg = crawrad_registry::Registry::builtin();

    reg.all().any(|c| c.events.iter().any(|e| e.name == evento))
}

#[note("targets-egui-stubs-e-marca-do-handler")]
fn e_marca_do_handler(linha: &str, nome: &str) -> bool {
    let t = linha.trim();
    let Some(miolo) = t.strip_prefix("/// `").and_then(|m| m.strip_suffix('`')) else {
        return false;
    };
    let Some((componente, evento)) = miolo.split_once('.') else {
        return false;
    };
    !componente.is_empty()
        && (eh_evento_conhecido(evento) || evento.starts_with("on_"))
        && crate::e_nome_derivado(componente, evento, nome)
}

fn corpo_vazio(corpo: &str) -> bool {
    corpo.lines().all(|l| l.trim().is_empty())
}

pub fn stubs(
    reg: &crawrad_registry::Registry,
    form: &str,
    tipo: &str,
    raiz: &Node,
    emitidos: &[&Node],
) -> Result<Arquivo, Erro> {
    stubs_with_base(reg, form, tipo, raiz, emitidos, None)
}

#[note("targets-egui-stubs-stubs-with-base")]
pub(crate) fn stubs_with_base(
    reg: &crawrad_registry::Registry,
    form: &str,
    tipo: &str,
    raiz: &Node,
    emitidos: &[&Node],
    inheritance: Option<(&Document, &Document)>,
) -> Result<Arquivo, Erro> {
    let mut corpo = String::new();
    let mut adicoes = Vec::new();

    // Which handlers belong to this document is a question for `crate::events`,
    // not this target: the designer uses it to decide WHICH payload types to emit, and
    // a second copy of the calculation here would let the designer and the user file
    // disagree on a type.
    for h in crate::events::wired_handlers(raiz, emitidos)? {
        let block = bloco_do_stub(reg, &h.node.class, h.node.name(), h.event, &h.name, None);
        corpo.push_str(&block);
        adicoes.push(Adicao {
            nome_da_fn: h.name.clone(),
            texto: format!("\nimpl {tipo} {{{block}}}\n"),
            ancora: Some(Ancora {
                marca: MARCA.to_string(),
                texto: block.clone(),
            }),
        });
    }

    if let Some((base_doc, doc)) = inheritance {
        for (id, derived_node) in &doc.nodes {
            if !doc.is_inherited(id, base_doc) {
                continue;
            }
            let base_node = base_doc.node(id);
            let class = base_node
                .map(|b| b.class.as_str())
                .filter(|c| !c.is_empty())
                .unwrap_or(derived_node.class.as_str());
            for (evento, alvo) in &derived_node.events {
                if alvo.trim().is_empty() {
                    continue;
                }
                let f = identificador(alvo)?;
                let base_h = base_node.and_then(|b| {
                    b.events
                        .iter()
                        .find(|(k, _)| k.eq_ignore_ascii_case(evento))
                        .map(|(_, v)| v.as_str())
                });
                let block = bloco_do_stub(reg, class, derived_node.name(), evento, &f, base_h);
                corpo.push_str(&block);
                adicoes.push(Adicao {
                    nome_da_fn: f.clone(),
                    texto: format!("\nimpl {tipo} {{{block}}}\n"),
                    ancora: Some(Ancora {
                        marca: MARCA.to_string(),
                        texto: block.clone(),
                    }),
                });
            }
        }
    }

    // **A single glob, and it is what avoids an `#[allow(unused_imports)]`.**
    //
    // The user file needs two things from the designer: the form type,
    // for the `impl`, and the event payload types (`KeyEvent`, `MouseEvent`),
    // which a handler signature names without a path. A `use` of only the
    // payload types would become unused on a form that wires no event using
    // them, and unused is a warning.
    //
    // The glob is never unused: the `impl` right below uses the form type
    // in every file, always. The warning ceases to exist instead of being
    // silenced, which is the law of the house.
    Ok(Arquivo {
        caminho: PathBuf::from(format!("src/{form}.rs")),
        conteudo: format!(
            "//! **This file is yours.** CrawRAD does not regenerate it, and it\n\
             //! never removes code you wrote.\n\
             //!\n\
             //! It does write to the file, though — better you know than be\n\
             //! surprised:\n\
             //!\n\
             //! - wiring a new event in the Object Inspector inserts the\n\
             //!   handler at the marker below, leaving the rest alone;\n\
             //! - generating takes empty event handlers back out, and\n\
             //!   saving generates — so saving takes them out too. It does\n\
             //!   not matter whether the event is still wired: the wiring\n\
             //!   is dropped in the same step, so the form still compiles.\n\
             //!   This only ever reaches a handler that is still the empty\n\
             //!   one CrawRAD wrote, under the very name CrawRAD gave it.\n\
             //!   Type one character into the body, even a comment; rename\n\
             //!   the function; or write a line of your own right above it,\n\
             //!   such as a doc comment or an attribute — any of these and\n\
             //!   it is yours: it stays for good.\n\
             //!   Methods you wrote yourself are never looked at, whatever\n\
             //!   you name them and whatever you write above them;\n\
             //! - renaming the form moves this file along with it and\n\
             //!   replaces the form's type name throughout — in your code\n\
             //!   AND in your comments — because otherwise it would not\n\
             //!   compile.\n\
             \n\
             // One glob, on purpose: it brings in the form's type, which\n\
             // the `impl` below is written on, and the event payload types\n\
             // (`KeyEvent`, `MouseEvent`) that a handler signature names\n\
             // with no path.\n\
             use crate::{form}_designer::*;\n\
             \n\
             impl {tipo} {{{corpo}{MARCA}}}\n"
        ),
        dono: Dono::Usuario,
        adicoes,
    })
}

pub fn podar(fonte: &str, ligados: &[&str], vizinhas: &[String]) -> (String, Vec<String>) {
    let mut cortes = podaveis(fonte, ligados, vizinhas);
    cortes.sort_by_key(|(r, _)| std::cmp::Reverse(r.start));
    let mut saida = fonte.to_string();
    for (r, _) in &cortes {
        saida.replace_range(r.clone(), "");
    }
    let mut nomes: Vec<String> = cortes.into_iter().map(|(_, n)| n).collect();
    nomes.sort();
    (saida, nomes)
}

pub fn podaveis(
    fonte: &str,
    protegidos: &[&str],
    vizinhas: &[String],
) -> Vec<(std::ops::Range<usize>, String)> {
    let mut cortes: Vec<(std::ops::Range<usize>, String)> = Vec::new();
    for (nome, local) in &elo::handlers_do_arquivo(fonte) {
        if protegidos.contains(&nome.as_str()) {
            continue;
        }
        let Some(ext) = elo::extensao_do_handler(fonte, local.byte) else {
            continue;
        };
        let Some(bloco) = bloco_marcado(fonte, &ext, nome) else {
            continue;
        };
        if !corpo_vazio(&fonte[ext.corpo.clone()]) {
            continue;
        }
        if elo::citado_fora(fonte, nome, bloco.clone()) {
            continue;
        }
        if vizinhas.iter().any(|v| elo::citado_fora(v, nome, 0..0)) {
            continue;
        }
        cortes.push((bloco, nome.clone()));
    }
    cortes
}

pub fn unidade_do_usuario(doc: &Document) -> Option<PathBuf> {
    let raiz = doc.node(&doc.root)?;
    let form = identificador(raiz.name()).ok()?;
    Some(PathBuf::from(format!("src/{form}.rs")))
}

pub fn vinculos(doc: &Document) -> Vec<(String, NodeId, String)> {
    let Some(raiz) = doc.node(&doc.root) else {
        return Vec::new();
    };
    let emitidos: Vec<&Node> = doc
        .in_paint_order()
        .iter()
        .filter_map(|id| doc.node(id))
        // a node that emits no code of its own (a GridColumn) still has its handlers linked
        .filter(|n| emitido(&n.class) || !n.events.is_empty())
        .collect();
    let mut fora = Vec::new();
    let mut vistos = std::collections::BTreeSet::new();
    for n in std::iter::once(raiz).chain(emitidos) {
        vistos.insert(&n.id);
        for (evento, alvo) in &n.events {
            let Ok(f) = identificador(alvo) else {
                continue;
            };
            fora.push((f, n.id.clone(), evento.clone()));
        }
    }
    if doc.inherits().is_some() {
        for (id, n) in &doc.nodes {
            if !vistos.contains(id) {
                for (evento, alvo) in &n.events {
                    let Ok(f) = identificador(alvo) else {
                        continue;
                    };
                    fora.push((f, n.id.clone(), evento.clone()));
                }
            }
        }
    }
    fora
}

fn bloco_marcado(fonte: &str, ext: &elo::Extensao, nome: &str) -> Option<std::ops::Range<usize>> {
    let fim_da_marca = ext.item.start.checked_sub(1)?;
    let inicio_da_marca = fonte[..fim_da_marca].rfind('\n').map(|p| p + 1)?;
    if !e_marca_do_handler(&fonte[inicio_da_marca..fim_da_marca], nome) {
        return None;
    }
    if !fecha_o_que_veio_antes(&fonte[..inicio_da_marca]) {
        return None;
    }
    let mut fim = ext.item.end;
    let resto = &fonte[fim..];
    let ate_a_quebra = resto.find('\n').map_or(resto.len(), |p| p);
    if resto[..ate_a_quebra].trim().is_empty() {
        fim += ate_a_quebra + usize::from(ate_a_quebra < resto.len());
    }
    let inicio = inicio_da_marca.checked_sub(1)?;
    let inicio = inicio - usize::from(fonte.as_bytes()[..inicio].last() == Some(&b'\r'));
    Some(inicio..fim)
}

#[note("targets-egui-stubs-fecha-o-que-veio-antes")]
fn fecha_o_que_veio_antes(acima: &str) -> bool {
    let Some(ultima) = acima.lines().rev().find(|l| !l.trim().is_empty()) else {
        return false;
    };
    let t = ultima.trim();
    !t.contains("//")
        && !t.starts_with('/')
        && !t.starts_with('#')
        && (t.ends_with('}') || t.ends_with('{') || t.ends_with(';'))
}

